1011	+// DeriveSourceState computes a SourceState from the latest SyncRun.
1012	+// When latestRun is nil, the workspace has never been synced — data is stale.
1013	+func DeriveSourceState(latestRun *SyncRun, staleThreshold time.Duration) SourceState {
1014	+	if latestRun == nil {
1015	+		return SourceState{Stale: true}
1016	+	}
1017	+
1018	+	switch latestRun.Status {
1019	+	case SyncStatusFailed:
1020	+		return SourceState{
1021	+			Stale:        true,
1022	+			LastSyncedAt: latestRun.FinishedAt,
1023	+			ErrorCode:    latestRun.ErrorCode,
1024	+			ErrorMessage: latestRun.ErrorMsg,
1025	+		}
1026	+	case SyncStatusSuccess, SyncStatusPartial:
1027	+		if latestRun.FinishedAt == nil {
1028	+			return SourceState{Stale: true}
1029	+		}
1030	+		age := time.Since(*latestRun.FinishedAt)
1031	+		return SourceState{
1032	+			Stale:        age > staleThreshold,
1033	+			LastSyncedAt: latestRun.FinishedAt,
1034	+		}
1035	+	case SyncStatusRunning:
1036	+		return SourceState{
1037	+			Stale:        false,
1038	+			LastSyncedAt: &latestRun.StartedAt,
1039	+		}
1040	+	default:
1041	+		return SourceState{Stale: true}
1042	+	}
1043	+}
