+func (f *fakeDB) ListGitHubSources(_ context.Context) ([]database.WorkspaceGitHubSource, error) {
+	out := make([]database.WorkspaceGitHubSource, 0, len(f.githubSrcs))
+	for _, src := range f.githubSrcs {
+		out = append(out, src)
+	}
+	return out, nil
