+	if f.getRunErr != nil {
+		return database.WorkspaceSyncRun{}, f.getRunErr
+	}
+	if len(f.syncRuns) > 0 {
+		return f.syncRuns[0], nil
+	}
+	return database.WorkspaceSyncRun{}, database.ErrNotFound
